fn contains_consecutive_numbers(a: &Vec<i32>) -> bool {
    // Check if the array has fewer than 2 elements
    if a.len() < 2 {
        return false;
    }

    // Iterate through the array and check for consecutive numbers
    for i in 0..(a.len() - 1) {
        if a[i] + 1 == a[i + 1] {
            return true; // Found a pair
        }
    }

    false // No such pair found
}